// Generated and vendored code (FR290 to FR299). Generated files are indexed and flagged, because a call often binds to them; vendored files
// are left out by rule, and an import into one resolves as an external package. The rules follow GitHub Linguist's `generated.rb` and
// `vendor.yml` (MIT), trimmed to what is stated in GENERATED_POLICY below, which workspace_status shows as it is.
import fs from 'node:fs'
import path from 'node:path'

/** A marker counts only in the first MARKER_LINES lines of the first MARKER_BYTES bytes: a phrase deep in code flags nothing. */
export const MARKER_LINES = 5
export const MARKER_BYTES = 1024

/** The outputs of well-known generators, by file name. */
const GENERATED_NAMES = [/\.pb\.go$/, /_pb2\.py$/, /_pb2_grpc\.py$/, /\.g\.cs$/, /\.Designer\.cs$/]
/** A marker is a comment: the same words in a string or an identifier on the first line are code. */
const COMMENT = /^(\/\/|\/\*|\*|#|<!--|--|;|')/
const GO_MARKER = /^\/\/ Code generated .* DO NOT EDIT\.\s*$/
const AT_GENERATED = /@generated\b/
const AUTO_GENERATED = /<auto-?generated/i

export const GENERATED_POLICY = {
  summary: 'Generated files are indexed and flagged generated; vendored files are excluded by rule and an import into one resolves as an external package. Hubs, dead code and entry points leave generated files out unless include_generated is passed, and say so. A linguist-generated or linguist-vendored attribute set to false overrides every other rule.',
  generated: 'indexed_and_flagged',
  vendored: 'excluded_by_rule',
  markers: ['Go: a line `// Code generated ... DO NOT EDIT.`', '`@generated` in a comment', '`<auto-generated` in a comment'],
  marker_window: { lines: MARKER_LINES, bytes: MARKER_BYTES },
  attributes: ['linguist-generated', 'linguist-vendored'],
  generated_names: ['*.pb.go', '*_pb2.py', '*_pb2_grpc.py', '*.g.cs', '*.Designer.cs'],
  vendored_paths: ['vendor/ beside vendor/modules.txt (vendored:go_vendor)', 'third_party/ (vendored:third_party)', 'Pods/ (vendored:pods)', 'linguist-vendored (vendored:linguist_vendored)'],
  build_output: ['build/ beside build.gradle, build.gradle.kts, settings.gradle or settings.gradle.kts (build_output:gradle)', 'target/ beside pom.xml (build_output:maven)', 'a directory holding CMakeCache.txt (build_output:cmake)', 'a path git ignores (gitignore)'],
  precedence: ['default excluded directories', 'gitignore', 'linguist attributes set to false', 'vendored', 'build output', 'generated'],
} as const

/** Whether the start of a file says it is generated: a marker inside the window, or the name of a known generator's output. */
export function isGeneratedFile(base: string, head: string): boolean {
  if (GENERATED_NAMES.some((re) => re.test(base))) return true
  const lines = head.slice(0, MARKER_BYTES).replace(/^﻿/, '').split('\n').slice(0, MARKER_LINES).map((l) => l.trim())
  return lines.some((l) => GO_MARKER.test(l) || (COMMENT.test(l) && (AT_GENERATED.test(l) || AUTO_GENERATED.test(l))))
}

type Rule = { re: RegExp; generated?: boolean | null; vendored?: boolean | null }
/** Each attribute is true, false, or null for unspecified (`!attr`); a rule that does not mention it leaves it alone. */
export type Attributes = { generated?: boolean; vendored?: boolean }

/** A .gitattributes pattern as a regular expression over a path relative to the file's directory. */
function patternToRegExp(pattern: string): RegExp {
  const anchored = pattern.replace(/\/+$/, '').includes('/')
  const body = pattern.replace(/^\//, '')
  let re = ''
  for (let i = 0; i < body.length; i++) {
    const c = body[i]!
    if (c === '*' && body[i + 1] === '*') {
      const lead = i === 0 || body[i - 1] === '/'
      if (lead && body[i + 2] === '/') { re += '(?:.*/)?'; i += 2 } else if (lead && i + 2 === body.length) { re += '.*'; i += 1 } else { re += '[^/]*'; i += 1 }
    } else if (c === '*') re += '[^/]*'
    else if (c === '?') re += '[^/]'
    else if (c === '[') {
      const end = body.indexOf(']', i + 2)
      if (end < 0) re += '\\['
      else { re += `[${body.slice(i + 1, end).replace(/^!/, '^').replace(/\\/g, '\\\\')}]`; i = end }
    } else re += c.replace(/[.+^${}()|\\\]]/g, '\\$&')
  }
  return new RegExp(`^${anchored ? '' : '(?:.*/)?'}${re}$`)
}

const ESCAPES: Record<string, number> = { a: 7, b: 8, f: 12, n: 10, r: 13, t: 9, v: 11, '\\': 92, '"': 34 }
/** A line whose pattern is C-quoted, as git writes a path with a space or a byte it escapes: the unquoted pattern, then the attributes. */
function splitQuoted(line: string): string[] {
  const bytes: number[] = []
  let i = 1
  for (; i < line.length && line[i] !== '"'; i++) {
    if (line[i] !== '\\') { bytes.splice(bytes.length, 0, ...Buffer.from(line[i]!)); continue }
    const octal = /^[0-3][0-7]{2}/.exec(line.slice(i + 1, i + 4))
    if (octal) { bytes.splice(bytes.length, 0, parseInt(octal[0], 8)); i += 3 } else if (ESCAPES[line[i + 1]!] !== undefined) bytes.splice(bytes.length, 0, ESCAPES[line[++i]!]!)
    else return []
  }
  return i >= line.length ? [] : [Buffer.from(bytes).toString('utf8'), ...line.slice(i + 1).trim().split(/\s+/)]
}

function parseAttributes(text: string): Rule[] {
  const rules: Rule[] = []
  for (const raw of text.split('\n')) {
    const line = raw.trim()
    if (!line || line.startsWith('#') || line.startsWith('[attr]')) continue
    const [pattern, ...attrs] = line.startsWith('"') ? splitQuoted(line) : line.split(/\s+/)
    if (!pattern) continue
    const rule: Rule = { re: patternToRegExp(pattern) }
    for (const a of attrs) {
      const m = /^(-|!)?linguist-(generated|vendored)(?:=(.*))?$/.exec(a)
      if (!m) continue
      rule[m[2] as 'generated' | 'vendored'] = m[1] === '!' ? null : m[1] === '-' ? false : m[3] === undefined ? true : m[3] !== 'false'
    }
    if ('generated' in rule || 'vendored' in rule) rules.push(rule)
  }
  return rules
}

/**
 * The linguist attributes of a path, from the .gitattributes files of its directory and every parent (the deepest line that names an
 * attribute wins, as in git). Read from the working tree only, so it needs no git; macros and .git/info/attributes are not read.
 */
export function attributeLookup(root: string): (rel: string) => Attributes {
  const files = new Map<string, Rule[]>()
  const rulesOf = (dir: string): Rule[] => {
    let rules = files.get(dir)
    if (!rules) {
      // O_NOFOLLOW: a .gitattributes that is a link is never read, so it cannot point outside the repository (discovery records it as a symlink).
      try {
        const fd = fs.openSync(path.join(root, dir, '.gitattributes'), fs.constants.O_RDONLY | fs.constants.O_NOFOLLOW)
        try { rules = parseAttributes(fs.readFileSync(fd, 'utf8')) } finally { fs.closeSync(fd) }
      } catch { rules = [] }
      files.set(dir, rules)
    }
    return rules
  }
  return (rel) => {
    const parts = rel.split('/')
    const out: Attributes = {}
    for (let i = 0; i < parts.length; i++) {
      const dir = parts.slice(0, i).join('/'), within = parts.slice(i).join('/')
      for (const rule of rulesOf(dir)) {
        if (!rule.re.test(within)) continue
        for (const k of ['generated', 'vendored'] as const) if (k in rule) { if (rule[k] === null) delete out[k]; else out[k] = rule[k]! }
      }
    }
    return out
  }
}
